        add(m, 173, 2, "Cleffa", "Star Shape Pokémon", "When numerous meteors illuminate the night sky, sightings of CLEFFA strangely increase.");
        add(m, 174, 2, "Igglybuff", "Balloon Pokémon", "Its extremely flexible and elastic body makes it bounce continuously--anytime, anywhere.");
        add(m, 175, 2, "Togepi", "Spike Ball Pokémon", "A proverb claims that happiness will come to anyone who can make a sleeping TOGEPI stand up.");
        add(m, 176, 2, "Togetic", "Happiness Pokémon", "It grows dispirited if it is not with kind people. It can float in midair without moving its wings.");
        add(m, 177, 2, "Natu", "Tiny Bird Pokémon", "It usually forages for food on the ground but may, on rare occasions, hop onto branches to peck at shoots.");
        add(m, 178, 2, "Xatu", "Mystic Pokémon", "In South America, it is said that its right eye sees the future and its left eye views the past.");
        add(m, 179, 2, "Mareep", "Wool Pokémon", "Its fleece grows continually. In the summer, the fleece is fully shed, but it grows back in a week.");
        add(m, 180, 2, "Flaaffy", "Wool Pokémon", "Its fluffy fleece easily stores electricity. Its rubbery hide keeps it from being electrocuted.");
        add(m, 181, 2, "Ampharos", "Light Pokémon", "The bright light on its tail can be seen far away. It has been treasured since ancient times as a beacon.");
        add(m, 182, 2, "Bellossom", "Flower Pokémon", "Plentiful in the tropics. When it dances, its petals rub together and make a pleasant ringing sound.");
        add(m, 183, 2, "Marill", "Aqua Mouse Pokémon", "The end of its tail serves as a buoy that keeps it from drowning, even in a vicious current.");
        add(m, 184, 2, "Azumarill", "Aqua Rabbit Pokémon", "When it plays in water, it rolls up its elongated ears to prevent their insides from getting wet.");
        add(m, 185, 2, "Sudowoodo", "Imitation Pokémon", "It disguises itself as a tree to avoid attack. It hates water, so it will disappear if it starts raining.");
        add(m, 186, 2, "Politoed", "Frog Pokémon", "Whenever three or more of these get together, they sing in a loud voice that sounds like bellowing.");
        add(m, 187, 2, "Hoppip", "Cottonweed Pokémon", "Its body is so light, it must grip the ground firmly with its feet to keep from being blown away.");
        add(m, 188, 2, "Skiploom", "Cottonweed Pokémon", "It spreads its petals to absorb sunlight. It also floats in the air to get closer to the sun.");
        add(m, 189, 2, "Jumpluff", "Cottonweed Pokémon", "It drifts on seasonal winds and spreads its cotton-like spores all over the world to make more offspring.");
        add(m, 190, 2, "Aipom", "Long Tail Pokémon", "It lives atop tall trees. When leaping from branch to branch, it deftly uses its tail for balance.");
        add(m, 191, 2, "Sunkern", "Seed Pokémon", "It lives by drinking only dewdrops from under the leaves of plants. It is said that it eats nothing else.");
        add(m, 192, 2, "Sunflora", "Sun Pokémon", "In the daytime, it rushes about in a hectic manner, but it comes to a complete stop when the sun sets.");
        add(m, 193, 2, "Yanma", "Clear Wing Pokémon", "Its large eyes can scan 360 degrees. It looks in all directions to seek out insects as its prey.");
        add(m, 194, 2, "Wooper", "Water Fish Pokémon", "When it walks around on the ground, it coats its body with a slimy, poisonous film.");
        add(m, 195, 2, "Quagsire", "Water Fish Pokémon", "Due to its relaxed and carefree attitude, it often bumps its head on boulders and boat hulls as it swims.");
        add(m, 196, 2, "Espeon", "Sun Pokémon", "By reading air currents, it can predict things such as the weather or its foe’s next move.");
        add(m, 197, 2, "Umbreon", "Moonlight Pokémon", "When darkness falls, the rings on its body begin to glow, striking fear in the hearts of anyone nearby.");
        add(m, 198, 2, "Murkrow", "Darkness Pokémon", "It is said that when chased, it lures its attacker onto dark mountain trails where the foe will get lost.");
        add(m, 199, 2, "Slowking", "Royal Pokémon", "When its head was bitten, toxins entered SLOWPOKE’s head and unlocked an extraordinary power.");
        add(m, 200, 2, "Misdreavus", "Screech Pokémon", "It loves to bite and yank people’s hair from behind without warning, just to see their shocked reactions.");
        add(m, 201, 2, "Unown", "Symbol Pokémon", "Its flat, thin body is always stuck on walls. Its shape appears to have some meaning.");
        add(m, 202, 2, "Wobbuffet", "Patient Pokémon", "To keep its pitch-black tail hidden, it lives quietly in the darkness. It is never first to attack.");
        add(m, 203, 2, "Girafarig", "Long Neck Pokémon", "Its tail, which also contains a small brain, may bite on its own if it notices an alluring smell.");
        add(m, 204, 2, "Pineco", "Bagworm Pokémon", "It hangs and waits for flying-insect prey to come near. It does not move about much on its own.");
        add(m, 205, 2, "Forretress", "Bagworm Pokémon", "It remains immovably rooted to its tree. It scatters pieces of its hard shell to drive its enemies away.");
        add(m, 206, 2, "Dunsparce", "Land Snake Pokémon", "If spotted, it escapes by burrowing with its tail. It can hover just slightly using its wings.");
        add(m, 207, 2, "Gligar", "Fly Scorpion Pokémon", "It usually clings to cliffs. When it spots its prey, it spreads its wings and glides down to attack.");
        add(m, 208, 2, "Steelix", "Iron Snake Pokémon", "It is said that if an ONIX lives for over 100 years, its composition changes to become diamond-like.");
        add(m, 209, 2, "Snubbull", "Fairy Pokémon", "It has an active, playful nature. Many women like to frolic with it because of its affectionate ways.");
        add(m, 210, 2, "Granbull", "Fairy Pokémon", "Because its fangs are too heavy, it always keeps its head tilted down. However, its BITE is powerful.");
        add(m, 211, 2, "Qwilfish", "Balloon Pokémon", "The small spikes covering its body developed from scales. They inject a toxin that causes fainting.");
        add(m, 212, 2, "Scizor", "Pincer Pokémon", "Its wings are not used for flying. They are flapped at high speed to adjust its body temperature.");
        add(m, 213, 2, "Shuckle", "Mold Pokémon", "It stores BERRIES inside its shell. To avoid attacks, it hides beneath rocks and remains completely still.");
        add(m, 214, 2, "Heracross", "Single Horn Pokémon", "Usually docile, but if disturbed while sipping honey, it chases off the intruder with its horn.");
        add(m, 215, 2, "Sneasel", "Sharp Claw Pokémon", "Vicious in nature, it drives PIDGEY from their nests and feasts on the eggs that are left behind.");
        add(m, 216, 2, "Teddiursa", "Little Bear Pokémon", "Before food becomes scarce in wintertime, its habit is to hoard food in many hidden locations.");
        add(m, 217, 2, "Ursaring", "Hibernator Pokémon", "With its ability to distinguish any smell, it unfailingly finds all food buried deep underground.");
        add(m, 218, 2, "Slugma", "Lava Pokémon", "A common sight in volcanic areas, it slowly slithers around in a constant search for warm places.");
        add(m, 219, 2, "Magcargo", "Lava Pokémon", "Its brittle shell occasionally spouts intense flames that circulate throughout its body.");
        add(m, 220, 2, "Swinub", "Pig Pokémon", "If it smells something enticing, it dashes off headlong to find the source of the aroma.");
        add(m, 221, 2, "Piloswine", "Swine Pokémon", "If it charges at an enemy, the hairs on its back stand up straight. It is very sensitive to sound.");
        add(m, 222, 2, "Corsola", "Coral Pokémon", "In a south sea nation, the people live in communities that are built on groups of these Pokémon.");
        add(m, 223, 2, "Remoraid", "Jet Pokémon", "Using its dorsal fin as a suction pad, it clings to a MANTINE’s underside to scavenge for leftovers.");
        add(m, 224, 2, "Octillery", "Jet Pokémon", "It instinctively sneaks into rocky holes. If it gets sleepy, it steals the nest of a fellow OCTILLERY.");
        add(m, 225, 2, "Delibird", "Delivery Pokémon", "It nests at the edge of sharp cliffs. It spends all day carrying food to its awaiting chicks.");
        add(m, 226, 2, "Mantine", "Kite Pokémon", "Swimming freely in open seas, it may fly out of the water and over the waves if it builds up enough speed.");
        add(m, 227, 2, "Skarmory", "Armor Bird Pokémon", "After nesting in bramble bushes, the wings of its chicks grow hard from scratches by thorns.");
        add(m, 228, 2, "Houndour", "Dark Pokémon", "To corner prey, they check each other’s location using barks that only they can understand.");
        add(m, 229, 2, "Houndoom", "Dark Pokémon", "Upon hearing its eerie howls, other Pokémon get the shivers and head straight back to their nests.");
        add(m, 230, 2, "Kingdra", "Dragon Pokémon", "It sleeps deep on the ocean floor to build its energy. It is said to cause tornadoes as it wakes.");
        add(m, 231, 2, "Phanpy", "Long Nose Pokémon", "As a sign of affection, it bumps with its snout. However, it is so strong, it may send you flying.");
        add(m, 232, 2, "Donphan", "Armor Pokémon", "The longer and bigger its tusks, the higher its rank in its herd. The tusks take a long time to grow.");
        add(m, 233, 2, "Porygon2", "Virtual Pokémon", "Further research enhanced its abilities. Sometimes, it may exhibit motions that were not programmed.");
        add(m, 234, 2, "Stantler", "Big Horn Pokémon", "Those who stare at its antlers will gradually lose control of their senses and be unable to stand.");
        add(m, 235, 2, "Smeargle", "Painter Pokémon", "Once it becomes an adult, it has a tendency to let its comrades plant footprints on its back.");
        add(m, 236, 2, "Tyrogue", "Scuffle Pokémon", "Even though it is small, it can’t be ignored because it will slug any handy target without warning.");
        add(m, 237, 2, "Hitmontop", "Handstand Pokémon", "It launches kicks while spinning. If it spins at high speed, it may bore its way into the ground.");
        add(m, 238, 2, "Smoochum", "Kiss Pokémon", "It always rocks its head slowly backwards and forwards as if it is trying to kiss someone.");
        add(m, 239, 2, "Elekid", "Electric Pokémon", "Even in the most vicious storm, this Pokémon plays happily if thunder rumbles in the sky.");
        add(m, 240, 2, "Magby", "Live Coal Pokémon", "It is found in volcanic craters. Its body heat exceeds 1,100 degrees Fahrenheit, so don’t underestimate it.");
        add(m, 241, 2, "Miltank", "Milk Cow Pokémon", "If it has just had a baby, the milk it produces contains much more nutrition than usual.");
        add(m, 242, 2, "Blissey", "Happiness Pokémon", "It has a very compassionate nature. If it sees a sick Pokémon, it will nurse the sufferer back to health.");
        add(m, 243, 2, "Raikou", "Thunder Pokémon", "This Pokémon races across the land while barking a cry that sounds like crashing thunder.");
        add(m, 244, 2, "Entei", "Volcano Pokémon", "A Pokémon that races across the land. It is said that one is born every time a new volcano appears.");
        add(m, 245, 2, "Suicune", "Aurora Pokémon", "This Pokémon races across the land. It is said that north winds will somehow blow whenever it appears.");
        add(m, 246, 2, "Larvitar", "Rock Skin Pokémon", "It is born deep underground. It can’t emerge until it has entirely consumed the soil around it.");
        add(m, 247, 2, "Pupitar", "Hard Shell Pokémon", "Even sealed in its shell, it can move freely. Hard and fast, it has outstanding destructive power.");
        add(m, 248, 2, "Tyranitar", "Armor Pokémon", "Its body can’t be harmed by any sort of attack, so it is very eager to make challenges against enemies.");
        add(m, 249, 2, "Lugia", "Diving Pokémon", "It is said to be the guardian of the seas. It is rumored to have been seen on the night of a storm.");
        add(m, 250, 2, "Ho-Oh", "Rainbow Pokémon", "A legend says that its body glows in seven colors. A rainbow is said to form behind it when it flies.");
        add(m, 251, 2, "Celebi", "Time Travel Pokémon", "When CELEBI disappears deep in a forest, it is said to leave behind an egg it brought from the future.");
        add(m, 252, 3, "Treecko", "Wood Gecko Pokémon", "It quickly scales even vertical walls. It senses humidity with its tail to predict the next day’s weather.");
        add(m, 253, 3, "Grovyle", "Wood Gecko Pokémon", "Its strongly developed thigh muscles give it astounding agility and jumping performance.");
        add(m, 254, 3, "Sceptile", "Forest Pokémon", "The leaves on its forelegs are as sharp as swords. It agilely leaps about the branches of trees to strike.");
        add(m, 255, 3, "Torchic", "Chick Pokémon", "It has a flame sac inside its belly that perpetually burns. It feels warm if it is hugged.");
        add(m, 256, 3, "Combusken", "Young Fowl Pokémon", "It boosts its concentration by emitting harsh cries. Its kicks have outstanding destructive power.");
        add(m, 257, 3, "Blaziken", "Blaze Pokémon", "When facing a tough foe, it looses flames from its wrists. Its powerful legs let it jump clear over buildings.");
        add(m, 258, 3, "Mudkip", "Mud Fish Pokémon", "Its large tail fin propels it through water with powerful acceleration. It is strong in spite of its size.");
        add(m, 259, 3, "Marshtomp", "Mud Fish Pokémon", "It is at its best when on muddy ground with poor footing. It quickly overwhelms foes struggling in mud.");
        add(m, 260, 3, "Swampert", "Mud Fish Pokémon", "Its arms are rock-hard. With one swing, they can batter down its foe. It makes its nest on beautiful beaches.");
        add(m, 261, 3, "Poochyena", "Bite Pokémon", "It has a very tenacious nature. Its acute sense of smell lets it chase a chosen prey without ever losing track.");
        add(m, 262, 3, "Mightyena", "Bite Pokémon", "It will always obey the commands of a skilled TRAINER. Its behavior arises from its living in packs in ancient times.");
        add(m, 263, 3, "Zigzagoon", "Tiny Raccoon Pokémon", "A Pokémon with abundant curiosity. It shows an interest in everything, so it always zigs and zags.");
        add(m, 264, 3, "Linoone", "Rushing Pokémon", "When running in a straight line, it can top 60 miles per hour. However, it has a tough time with curved roads.");
        add(m, 265, 3, "Wurmple", "Worm Pokémon", "It lives amidst tall grass and in forests. When attacked, it resists by pointing its venomous spikes at the foe.");
        add(m, 266, 3, "Silcoon", "Cocoon Pokémon", "It conserves its energy by moving as little as possible. It awaits evolution while drinking only a little rainwater.");
        add(m, 267, 3, "Beautifly", "Butterfly Pokémon", "Despite its appearance, it has an aggressive nature. It attacks by jabbing with its long, thin mouth.");
        add(m, 268, 3, "Cascoon", "Cocoon Pokémon", "Its body, which is made of soft silk, hardens over time. When cracks appear, evolution is near.");
        add(m, 269, 3, "Dustox", "Poison Moth Pokémon", "It scatters horribly toxic dust when it senses danger. They tend to gather in the glow of streetlamps at night.");
        add(m, 270, 3, "Lotad", "Water Weed Pokémon", "It searches about for clean water. If it does not drink water for too long, the leaf on its head wilts.");
        add(m, 271, 3, "Lombre", "Jolly Pokémon", "It lives at the water’s edge where it is sunny. It sleeps on a bed of water grass by day and becomes active at night.");
        add(m, 272, 3, "Ludicolo", "Carefree Pokémon", "The rhythm of bright, festive music activates LUDICOLO’s cells, making it more powerful.");
        add(m, 273, 3, "Seedot", "Acorn Pokémon", "If it remains still, it becomes impossible to distinguish from real nuts. It delights in surprising foraging PIDGEY.");
        add(m, 274, 3, "Nuzleaf", "Wily Pokémon", "They live in holes bored in large trees. The sound of NUZLEAF’s grass flute fills listeners with dread.");
        add(m, 275, 3, "Shiftry", "Wicked Pokémon", "A Pokémon that was feared as a forest guardian. It can read the foe’s mind and take preemptive action.");
        add(m, 276, 3, "Taillow", "Tiny Swallow Pokémon", "It dislikes cold seasons. They migrate to other lands in search of warmth, flying over 180 miles a day.");
        add(m, 277, 3, "Swellow", "Swallow Pokémon", "If its two tail feathers are standing at attention, it is proof of good health. It soars elegantly in the sky.");
        add(m, 278, 3, "Wingull", "Seagull Pokémon", "It rides upon ocean winds as if it were a glider. In the winter, it hides food around its nest.");
        add(m, 279, 3, "Pelipper", "Water Bird Pokémon", "It is a flying transporter that carries small Pokémon in its beak. It bobs on the waves to rest its wings.");
        add(m, 280, 3, "Ralts", "Feeling Pokémon", "It is highly attuned to the emotions of people and Pokémon. It hides if it senses hostility.");
        add(m, 281, 3, "Kirlia", "Emotion Pokémon", "The cheerful spirit of its TRAINER gives it energy for its psychokinetic power. It spins and dances when happy.");
        add(m, 282, 3, "Gardevoir", "Embrace Pokémon", "It has the power to predict the future. Its power peaks when it is protecting its TRAINER.");
        add(m, 283, 3, "Surskit", "Pond Skater Pokémon", "They usually live on ponds, but after an evening shower, they may appear on puddles in towns.");
        add(m, 284, 3, "Masquerain", "Eyeball Pokémon", "The antennae have distinctive patterns that look like eyes. When it rains, they grow heavy, making flight impossible.");
        add(m, 285, 3, "Shroomish", "Mushroom Pokémon", "It prefers damp places. By day it remains still in the forest shade. It releases toxic powder from its head.");
        add(m, 286, 3, "Breloom", "Mushroom Pokémon", "The seeds on its tail are made of toxic spores. It knocks out foes with quick, virtually invisible punches.");
        add(m, 287, 3, "Slakoth", "Slacker Pokémon", "It sleeps for 20 hours every day. Making drowsy those that see it is one of its abilities.");
        add(m, 288, 3, "Vigoroth", "Wild Monkey Pokémon", "It is always hungry because it won’t stop rampaging. Even while it is eating, it can’t keep still.");
        add(m, 289, 3, "Slaking", "Lazy Pokémon", "It is the world’s most slothful Pokémon. However, it can exert horrifying power by releasing pent-up energy all at once.");
        add(m, 290, 3, "Nincada", "Trainee Pokémon", "Because it lived almost entirely underground, it is nearly blind. It uses its antennae instead.");
        add(m, 291, 3, "Ninjask", "Ninja Pokémon", "This Pokémon is so quick, it is said to be able to avoid any attack. It loves to feed on tree sap.");
        add(m, 292, 3, "Shedinja", "Shed Pokémon", "A most peculiar Pokémon that somehow appears in a POKé BALL when a NINCADA evolves.");
        add(m, 293, 3, "Whismur", "Whisper Pokémon", "It usually murmurs, but starts crying loudly if it senses danger. It stops when its ear covers are shut.");
        add(m, 294, 3, "Loudred", "Big Voice Pokémon", "When it stamps its feet and bellows, it generates ultrasonic waves that can blow apart a house.");
        add(m, 295, 3, "Exploud", "Loud Noise Pokémon", "It emits a variety of sounds from the holes all over its body. Its loud cries can be heard from over six miles away.");
        add(m, 296, 3, "Makuhita", "Guts Pokémon", "It grows stronger by enduring harsh training. It is a gutsy Pokémon that can withstand any attack.");
        add(m, 297, 3, "Hariyama", "Arm Thrust Pokémon", "It stomps on the ground to build power. It can send a 10-ton truck flying with a straight-arm punch.");
        add(m, 298, 3, "Azurill", "Polka Dot Pokémon", "It battles by flinging around its tail, which is bigger than its body. The tail is a flotation device in water.");
        add(m, 299, 3, "Nosepass", "Compass Pokémon", "Its magnetic nose consistently faces north. Travelers check NOSEPASS to get their bearings.");
        add(m, 300, 3, "Skitty", "Kitten Pokémon", "It is said to be difficult to earn its trust. However, it is extremely popular for its cute looks and behavior.");
        add(m, 301, 3, "Delcatty", "Prim Pokémon", "The favorite of trend-conscious female TRAINERS, they are used in competition for their style and fur.");
        add(m, 302, 3, "Sableye", "Darkness Pokémon", "It feeds on gemstone crystals. In darkness, its eyes sparkle with the glitter of jewels.");
        add(m, 303, 3, "Mawile", "Deceiver Pokémon", "It uses its docile-looking face to lull foes into complacency, then bites with its huge, relentless jaws.");
        add(m, 304, 3, "Aron", "Iron Armor Pokémon", "It eats iron to build its steel body. It is a pest that descends from mountains to eat bridges and train tracks.");
        add(m, 305, 3, "Lairon", "Iron Armor Pokémon", "It habitually shows off its strength with the size of sparks it creates by ramming its steel body into boulders.");
        add(m, 306, 3, "Aggron", "Iron Armor Pokémon", "It claims a large mountain as its sole territory. It mercilessly thrashes those that violate its space.");
        add(m, 307, 3, "Meditite", "Meditate Pokémon", "It never skips its daily yoga training. It heightens its inner strength through meditation.");
        add(m, 308, 3, "Medicham", "Meditate Pokémon", "It elegantly avoids attacks with dance- like steps, then launches a devastating blow in the same motion.");
        add(m, 309, 3, "Electrike", "Lightning Pokémon", "It stores static electricity in its fur for discharging. It gives off sparks if a storm approaches.");
        add(m, 310, 3, "Manectric", "Discharge Pokémon", "It rarely appears before people. It is said to nest where lightning has fallen.");
        add(m, 311, 3, "Plusle", "Cheering Pokémon", "It cheers on partners while scattering sparks from its body. It climbs telephone poles to absorb electricity.");
        add(m, 312, 3, "Minun", "Cheering Pokémon", "Its dislike of water makes it take shelter under the eaves of houses in rain. It uses pom-poms made of sparks for cheering.");
        add(m, 313, 3, "Volbeat", "Firefly Pokémon", "It lives around clean ponds. At night, its rear lights up. It converses with others by flashing its light.");
        add(m, 314, 3, "Illumise", "Firefly Pokémon", "It guides VOLBEAT to draw signs in night skies. There are scientists that study the patterns it creates.");
        add(m, 315, 3, "Roselia", "Thorn Pokémon", "Its flowers give off a relaxing fragrance. The stronger its aroma, the healthier the ROSELIA is.");
        add(m, 316, 3, "Gulpin", "Stomach Pokémon", "There is nothing its stomach can’t digest. While it is digesting, vile, overpowering gases are expelled.");
        add(m, 317, 3, "Swalot", "Poison Bag Pokémon", "It can swallow a tire whole in one gulp. It secretes a horribly toxic fluid from the pores on its body.");
        add(m, 318, 3, "Carvanha", "Savage Pokémon", "It lives in massive rivers that course through jungles. It swarms prey that enter its territory.");
        add(m, 319, 3, "Sharpedo", "Brutal Pokémon", "The ruffian of the seas, it has fangs that crunch through iron. It swims by jetting water from its rear.");
        add(m, 320, 3, "Wailmer", "Ball Whale Pokémon", "When it sucks in a large volume of seawater, it becomes like a big, bouncy ball. It eats a ton of food daily.");
        add(m, 321, 3, "Wailord", "Float Whale Pokémon", "It is among the largest of all Pokémon. It herds prey in a pack then swallows the massed prey in one gulp.");
        add(m, 322, 3, "Numel", "Numb Pokémon", "Magma of almost 2,200 degrees Fahrenheit courses through its body. When it grows cold, the magma hardens and slows it.");
        add(m, 323, 3, "Camerupt", "Eruption Pokémon", "If angered, the humps on its back erupt in a shower of molten lava. It lives in the craters of volcanoes.");
        add(m, 324, 3, "Torkoal", "Coal Pokémon", "It burns coal inside its shell. If it is attacked, it belches thick, black smoke and flees.");
        add(m, 325, 3, "Spoink", "Bounce Pokémon", "It apparently dies if it stops bouncing about. It carries a pearl from CLAMPERL on its head.");
        add(m, 326, 3, "Grumpig", "Manipulate Pokémon", "It can gain control over foes by doing odd dance steps. The black pearls on its forehead are precious gems.");
        add(m, 327, 3, "Spinda", "Spot Panda Pokémon", "No two SPINDA are said to have identical patterns. It confuses foes with its stumbling motions.");
        add(m, 328, 3, "Trapinch", "Ant Pit Pokémon", "It lives in arid deserts. It makes a sloping pit trap in sand where it patiently awaits prey.");
        add(m, 329, 3, "Vibrava", "Vibration Pokémon", "It generates ultrasonic waves by violently flapping its wings. After making its prey faint, it melts the prey with acid.");
        add(m, 330, 3, "Flygon", "Mystic Pokémon", "It hides itself by kicking up desert sand with its wings. Red covers shield its eyes from sand.");
        add(m, 331, 3, "Cacnea", "Cactus Pokémon", "It prefers harsh environments such as deserts. It can survive for 30 days on water stored in its body.");
        add(m, 332, 3, "Cacturne", "Scarecrow Pokémon", "It lives in deserts. It becomes active at night when it hunts for prey exhausted from the desert’s heat.");
        add(m, 333, 3, "Swablu", "Cotton Bird Pokémon", "It constantly grooms its cotton-like wings. It takes a shower to clean itself if it becomes dirty.");
        add(m, 334, 3, "Altaria", "Humming Pokémon", "If you hear a beautiful melody trilling deep among mountains far from people, it is ALTARIA’s humming.");
        add(m, 335, 3, "Zangoose", "Cat Ferret Pokémon", "If it comes across a SEVIPER, its fur bristles and it assumes its battle pose. Its sharp claws are its best weapon.");
        add(m, 336, 3, "Seviper", "Fang Snake Pokémon", "It sharpens its swordlike tail on hard rocks. It hides in tall grass and strikes unwary prey with venomous fangs.");
        add(m, 337, 3, "Lunatone", "Meteorite Pokémon", "Its health ebbs and flows with the lunar cycle. It brims with power when exposed to the light of the full moon.");
        add(m, 338, 3, "Solrock", "Meteorite Pokémon", "It absorbs solar energy during the day. Always expressionless, it can sense what its foe is thinking.");
        add(m, 339, 3, "Barboach", "Whiskers Pokémon", "It probes muddy riverbeds with its two long whiskers. A slimy film protects its body.");
        add(m, 340, 3, "Whiscash", "Whiskers Pokémon", "It makes its nest at the bottom of swamps. It will eat anything - if it is alive, WHISCASH will eat it.");
        add(m, 341, 3, "Corphish", "Ruffian Pokémon", "It came from overseas. It is a very hardy creature that will quickly proliferate, even in polluted streams.");
        add(m, 342, 3, "Crawdaunt", "Rogue Pokémon", "A rough customer that wildly flails its giant claws. It is said to be extremely hard to raise.");
        add(m, 343, 3, "Baltoy", "Clay Doll Pokémon", "It was discovered in ancient ruins. While moving, it constantly spins. It stands on one foot even when asleep.");
        add(m, 344, 3, "Claydol", "Clay Doll Pokémon", "It appears to have been born from clay dolls made by ancient people. It uses telekinesis to float and move.");
        add(m, 345, 3, "Lileep", "Sea Lily Pokémon", "It became extinct roughly 100 million years ago. It was regenerated from a fossil using advanced techniques.");
        add(m, 346, 3, "Cradily", "Barnacle Pokémon", "It ensnares prey with its eight tentacles. It then melts the prey with a strong acid before feeding.");
        add(m, 347, 3, "Anorith", "Old Shrimp Pokémon", "It is a kind of Pokémon progenitor. It uses its extending claws to catch prey hiding among rocks on the seafloor.");
        add(m, 348, 3, "Armaldo", "Plate Pokémon", "Protected by a hard shell, its body is very sturdy. It skewers prey with its claws to feed.");
        add(m, 349, 3, "Feebas", "Fish Pokémon", "Ridiculed for its shabby appearance, it is ignored by researchers. It lives in ponds choked with weeds.");
        add(m, 350, 3, "Milotic", "Tender Pokémon", "MILOTIC is breathtakingly beautiful. Those that see it are said to forget their combative spirits.");
        add(m, 351, 3, "Castform", "Weather Pokémon", "It has the ability to change its form into the sun, the rain, or a snow cloud, depending on the weather.");
