        add(m, 360, 3, "Wynaut", "Bright Pokémon", "It tends to move in a pack with others. They cluster in a tight group to sleep in a cave.");
        add(m, 361, 3, "Snorunt", "Snow Hat Pokémon", "It is said that a home visited by a SNORUNT will prosper. It can withstand cold of minus 150 degrees Fahrenheit.");
