        add(m, 377, 3, "Regirock", "Rock Peak Pokémon", "It is entirely composed of rocks with no sign of a brain or heart. It is a mystery even to modern scientists.");
        add(m, 378, 3, "Regice", "Iceberg Pokémon", "Research revealed that its body is made of the same kind of ice that is found at the South Pole.");
        add(m, 379, 3, "Registeel", "Iron Pokémon", "It is sturdier than any kind of metal. It hardened due to pressure underground over tens of thousands of years.");
