        add(m, 389, 4, "Torterra", "Continent Pokémon", "Ancient people imagined that beneath the ground, a gigantic Torterra dwelled.");
        add(m, 390, 4, "Chimchar", "Chimp Pokémon", "Its fiery rear end is fueled by gas made in its belly. Even rain can’t extinguish the fire.");
        add(m, 391, 4, "Monferno", "Playful Pokémon", "It skillfully controls the intensity of the fire on its tail to keep its foes at an ideal distance.");
        add(m, 392, 4, "Infernape", "Flame Pokémon", "Its crown of fire is indicative of its fiery nature. It is beaten by none in terms of quickness.");
