        add(m, 397, 4, "Staravia", "Starling Pokémon", "They maintain huge flocks, although fierce scuffles break out between various flocks.");
        add(m, 398, 4, "Staraptor", "Predator Pokémon", "The muscles in its wings and legs are strong. It can easily fly while gripping a small Pokémon.");
        add(m, 399, 4, "Bidoof", "Plump Mouse Pokémon", "With nerves of steel, nothing can perturb it. It is more agile and active than it appears.");
        add(m, 400, 4, "Bibarel", "Beaver Pokémon", "It busily makes its nest with stacks of branches and roots it has cut up with its sharp incisors.");
